// Shared by both custom nodes. Levels are RMS observations, not audio samples.
export function decibels(rms) {
  return rms > 0 ? 20 * Math.log10(rms) : -Infinity;
}
export function normalizedLevel(db, floor) {
  return Math.min(1, Math.max(0, (db - floor) / -floor));
}
export function formatLevel(db) {
  return Number.isFinite(db) ? db.toFixed(1) : '−∞';
}
export function surface(element, title, detail) {
  const root = document.createElement('section');
  root.style.cssText =
    'box-sizing:border-box;height:100%;padding:18px;display:flex;flex-direction:column;gap:12px;background:oklch(21% .012 245);color:oklch(92% .01 245);font:13px system-ui;overflow:auto';
  const heading = document.createElement('strong');
  heading.textContent = title;
  heading.style.cssText = 'font-size:15px;font-weight:600';
  const note = document.createElement('span');
  note.textContent = detail;
  note.style.cssText = 'color:oklch(73% .02 245);font-size:12px;line-height:1.5';
  const status = document.createElement('span');
  status.style.cssText = 'font-size:12px;color:oklch(73% .02 245)';
  root.append(heading, note);
  element.append(root);
  return { root, status };
}

import { decibels, normalizedLevel, formatLevel, surface } from './levels.mjs';

export default function createLevelMeter() {
  return {
    mount(element, api) {
      const { root, status } = surface(element, 'Output level', 'RMS · after output gain');
      const reading = document.createElement('output');
      reading.style.cssText =
        'font:28px ui-monospace,monospace;font-variant-numeric:tabular-nums;margin-top:auto';
      const track = document.createElement('div');
      track.setAttribute('role', 'meter');
      track.setAttribute('aria-label', 'Output RMS in dBFS');
      track.style.cssText = 'height:32px;background:oklch(28% .014 245);overflow:hidden;flex:none';
      const fill = document.createElement('div');
      fill.style.cssText = 'height:100%;transform-origin:left;background:oklch(76% .1 205)';
      track.append(fill);
      const scale = document.createElement('div');
      scale.style.cssText =
        'display:flex;justify-content:space-between;font:11px ui-monospace,monospace;color:oklch(73% .02 245)';
      const low = document.createElement('span'),
        middle = document.createElement('span'),
        high = document.createElement('span');
      scale.append(low, middle, high);
      status.style.marginBottom = 'auto';
      root.append(reading, track, scale, status);
      let frame;
      function draw() {
        const signal = api.input('analysis');
        const floor = api.parameter('floorDb');
        const db = decibels(signal?.rms ?? 0);
        reading.textContent = signal ? `${formatLevel(db)} dBFS` : 'No analysis';
        fill.style.transform = `scaleX(${signal ? normalizedLevel(db, floor) : 0})`;
        fill.style.background = db >= 0 ? 'oklch(74% .13 35)' : 'oklch(76% .1 205)';
        low.textContent = String(floor);
        middle.textContent = String(floor / 2);
        high.textContent = '0 dBFS';
        track.setAttribute('aria-valuemin', String(floor));
        track.setAttribute('aria-valuemax', '0');
        track.setAttribute('aria-valuenow', String(Math.max(floor, Math.min(0, db))));
        track.setAttribute('aria-valuetext', reading.textContent);
        status.textContent = signal
          ? `RMS ${signal.rms.toFixed(4)}`
          : 'Connect Output.analysis and start audio.';
        root.dataset.rms = String(signal?.rms ?? 0);
        root.dataset.db = String(db);
        frame = requestAnimationFrame(draw);
      }
      draw();
      return {
        dispose() {
          cancelAnimationFrame(frame);
          root.remove();
        },
      };
    },
  };
}

import { decibels, normalizedLevel, surface } from './levels.mjs';

export default function createLevelHistory() {
  return {
    mount(element, api) {
      const { root, status } = surface(
        element,
        'Level history',
        'Output RMS over time · not an audio waveform',
      );
      const canvas = document.createElement('canvas');
      canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', 'Recent output RMS level in dBFS');
      canvas.style.cssText = 'width:100%;min-height:100px;flex:1;min-width:0';
      root.append(canvas, status);
      const context = canvas.getContext('2d');
      const points = [];
      let frame,
        lastSample = -Infinity;
      function draw() {
        const signal = api.input('analysis');
        const now = performance.now(),
          seconds = api.parameter('seconds'),
          floor = api.parameter('floorDb');
        if (signal && now - lastSample >= 40) {
          points.push({ time: now, db: decibels(signal.rms) });
          lastSample = now;
        }
        if (!signal) points.length = 0;
        while (points.length && points[0].time < now - seconds * 1000) points.shift();
        const ratio = Math.min(devicePixelRatio || 1, 2);
        const width = Math.max(1, canvas.clientWidth),
          height = Math.max(1, canvas.clientHeight);
        if (
          canvas.width !== Math.round(width * ratio) ||
          canvas.height !== Math.round(height * ratio)
        ) {
          canvas.width = Math.round(width * ratio);
          canvas.height = Math.round(height * ratio);
        }
        context.setTransform(ratio, 0, 0, ratio, 0, 0);
        context.clearRect(0, 0, width, height);
        const left = 32,
          top = 16,
          right = width - 8,
          bottom = height - 24;
        context.font = '11px system-ui';
        context.lineWidth = 1;
        for (const db of [0, floor / 2, floor]) {
          const y = bottom - normalizedLevel(db, floor) * (bottom - top);
          context.strokeStyle = '#38434c';
          context.beginPath();
          context.moveTo(left, y);
          context.lineTo(right, y);
          context.stroke();
          context.fillStyle = '#abb7c1';
          context.fillText(String(db), 0, y + 4);
        }
        context.fillStyle = '#abb7c1';
        context.fillText(`−${seconds.toFixed(0)} s`, left, height - 4);
        context.textAlign = 'right';
        context.fillText('now', right, height - 4);
        context.textAlign = 'left';
        context.strokeStyle = '#88cad9';
        context.lineWidth = 2;
        context.beginPath();
        points.forEach((point, index) => {
          const x = right - ((now - point.time) / (seconds * 1000)) * (right - left);
          const y = bottom - normalizedLevel(point.db, floor) * (bottom - top);
          if (index === 0) context.moveTo(x, y);
          else context.lineTo(x, y);
        });
        context.stroke();
        status.textContent = signal
          ? 'Change Output gain to trace a level change.'
          : 'Connect Output.analysis and start audio.';
        root.dataset.samples = String(points.length);
        root.dataset.rms = String(signal?.rms ?? 0);
        frame = requestAnimationFrame(draw);
      }
      draw();
      return {
        dispose() {
          cancelAnimationFrame(frame);
          root.remove();
        },
      };
    },
  };
}
